import type { CSSProperties, FC } from 'react';
import { Doughnut as ChartJsDoughnut } from 'react-chartjs-2';

import type { ChartData, ChartOptions } from 'chart.js';
import ChartDataLabels from 'chartjs-plugin-datalabels';
import { registerChartModules } from 'components/Chart/register';
import { merge } from 'lodash';

registerChartModules();

export const defaultDoughnutOptions: ChartOptions<'doughnut'> = {
  responsive: true,
  maintainAspectRatio: false,
  cutout: '82%',
  spacing: 3,
  layout: {
    padding: { top: 22, bottom: 32, left: 22, right: 22 },
  },
  plugins: {
    legend: { display: false },
    tooltip: {
      callbacks: {
        label: (ctx) => {
          const value = ctx.raw as number;
          return ` ${ctx.label}: ${value}%`;
        },
      },
    },
    datalabels: {
      clip: false,
      anchor: 'end',
      align: 'end',
      offset: 10,
      textAlign: 'center',
      color: '#0D0D0C',
      font: {
        size: 18,
        family: "'Work Sans', sans-serif",
        lineHeight: 1.4,
      },
      formatter: (value: number) => `${value}%`,
    },
  },
};

function toCssSize(value: number | string): string {
  return typeof value === 'number' ? `${value}px` : value;
}

export interface DoughnutProps {
  data: ChartData<'doughnut'>;
  options?: ChartOptions<'doughnut'>;
  dataTestId?: string;
  height?: number | string;
  width?: number | string;
}

export const Doughnut: FC<DoughnutProps> = ({
  data,
  options,
  dataTestId,
  height,
  width,
}) => {
  const wrapperStyle: CSSProperties = {
    position: 'relative',
    ...(width === undefined ? {} : { width: toCssSize(width) }),
    ...(height === undefined ? {} : { height: toCssSize(height) }),
  };

  return (
    <div data-testid={dataTestId} style={wrapperStyle}>
      <ChartJsDoughnut
        data={data}
        options={merge({}, defaultDoughnutOptions, options)}
        plugins={[ChartDataLabels]}
      />
    </div>
  );
};
